/**
 * Pending-compile warm-up tier (M5 of {@code .agent/lmdb-kernel-interpreter-execplan.md}): with janino ENABLED but the
 * compile deterministically unavailable (thresholdRows = Long.MAX_VALUE forces the below-threshold decline with no
 * async race), {@code rdf4j.lmdb.kernelInterpreter.warmup=true} must serve the interpreter on both rungs — proven by
 * the AGG_OPENED/OPENED counters, which only the kernel rungs advance — while warmup off keeps today's decline (the
 * counters stay at zero and the interpreted ladder still answers correctly).
 */
class LmdbNativeKernelInterpreterWarmupTest {

	private static final String EX = "http://example.com/warm/";

	private static final String[] PROPERTIES = {
			"rdf4j.lmdb.nativeQueryEngine.enabled",
			"rdf4j.lmdb.janinoCodegen.enabled",
			"rdf4j.lmdb.janinoCodegen.thresholdRows",
			"rdf4j.lmdb.janinoCodegen.synchronous",
			"rdf4j.lmdb.kernelInterpreter.enabled",
			"rdf4j.lmdb.kernelInterpreter.warmup",
			"rdf4j.lmdb.wcoj.enabled",
			"rdf4j.lmdb.factorizedRows.enabled",
			"rdf4j.lmdb.factorizedTail.enabled",
			"rdf4j.lmdb.nativeBatch.enabled",
			"rdf4j.lmdb.packedFtree.enabled",
			"rdf4j.lmdb.prefixRun.enabled",
			"rdf4j.lmdb.parallel.enabled",
			"rdf4j.lmdb.parallel.threads",
			"rdf4j.lmdb.irAggregateParallel.enabled" };

	private static final String AGGREGATE_QUERY = "PREFIX ex: <" + EX + ">\n"
			+ "SELECT (COUNT(*) AS ?c) WHERE { ?p ex:hasEncounter ?e }";
	private static final String ROW_QUERY = "PREFIX ex: <" + EX + ">\n"
			+ "SELECT ?p ?d WHERE { ?p ex:hasEncounter ?e . ?e ex:code ?d }";

	@TempDir
	File dataDir;

	private final Map<String, String> previousProperties = new HashMap<>();
	private SailRepository repository;

	@BeforeEach
	void setUp() {
		for (String property : PROPERTIES) {
			previousProperties.put(property, System.getProperty(property));
		}
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
		// Deterministically below threshold: the codegen cache returns null without scheduling anything.
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", Long.toString(Long.MAX_VALUE));
		System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "false");
		System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "true");
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedRows.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedTail.enabled", "false");
		System.setProperty("rdf4j.lmdb.nativeBatch.enabled", "false");
		System.setProperty("rdf4j.lmdb.packedFtree.enabled", "false");
		System.setProperty("rdf4j.lmdb.prefixRun.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.threads", "1");
		System.setProperty("rdf4j.lmdb.irAggregateParallel.enabled", "false");

		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbStore store = new LmdbStore(dataDir, config);
		repository = new SailRepository(store);
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI hasEncounter = vf.createIRI(EX, "hasEncounter");
			IRI code = vf.createIRI(EX, "code");
			conn.begin();
			for (int i = 0; i < 20; i++) {
				IRI patient = vf.createIRI(EX, "patient" + i);
				for (int j = 0; j <= i % 2; j++) {
					IRI encounter = vf.createIRI(EX, "enc" + i + "_" + j);
					conn.add(patient, hasEncounter, encounter);
					conn.add(encounter, code, vf.createLiteral(i * 10 + j));
				}
			}
			conn.commit();
		}
		try {
			assertThat(store.awaitDirectAdjacencyReady(60, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IllegalStateException(e);
		}
	}

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		for (Map.Entry<String, String> property : previousProperties.entrySet()) {
			if (property.getValue() == null) {
				System.clearProperty(property.getKey());
			} else {
				System.setProperty(property.getKey(), property.getValue());
			}
		}
	}

	@Test
	void warmupServesTheAggregateRungWhileTheCompileIsUnavailable() {
		List<String> expected = generic(AGGREGATE_QUERY);
		System.setProperty("rdf4j.lmdb.kernelInterpreter.warmup", "true");
		LmdbNativeKernelExecution.resetMetrics();
		assertThat(nativeRows(AGGREGATE_QUERY)).isEqualTo(expected);
		assertThat(LmdbNativeKernelExecution.AGG_OPENED.get())
				.as("warmup must serve the interpreter for a below-threshold compile")
				.isPositive();
		assertThat(JaninoPipelineTestAccess.openedAny())
				.as("an interpreted aggregate must not count as an opened compiled kernel")
				.isZero();
	}

	@Test
	void warmupOffKeepsTheBelowThresholdDecline() {
		List<String> expected = generic(AGGREGATE_QUERY);
		System.setProperty("rdf4j.lmdb.kernelInterpreter.warmup", "false");
		LmdbNativeKernelExecution.resetMetrics();
		assertThat(nativeRows(AGGREGATE_QUERY)).isEqualTo(expected);
		assertThat(LmdbNativeKernelExecution.AGG_OPENED.get())
				.as("without warmup a below-threshold compile must keep today's decline")
				.isZero();
	}

	@Test
	void warmupServesTheRowRungWhileTheCompileIsUnavailable() {
		List<String> expected = generic(ROW_QUERY);
		System.setProperty("rdf4j.lmdb.kernelInterpreter.warmup", "true");
		LmdbNativeKernelExecution.resetMetrics();
		assertThat(nativeRows(ROW_QUERY)).isEqualTo(expected);
		assertThat(LmdbNativeKernelExecution.OPENED.get())
				.as("warmup must serve the row interpreter for a below-threshold compile")
				.isPositive();
		assertThat(JaninoPipelineTestAccess.openedAny())
				.as("an interpreted row kernel must not count as an opened compiled kernel")
				.isZero();
	}

	@Test
	void warmupOffKeepsTheRowRungDecline() {
		List<String> expected = generic(ROW_QUERY);
		System.setProperty("rdf4j.lmdb.kernelInterpreter.warmup", "false");
		LmdbNativeKernelExecution.resetMetrics();
		assertThat(nativeRows(ROW_QUERY)).isEqualTo(expected);
		assertThat(LmdbNativeKernelExecution.OPENED.get())
				.as("without warmup a below-threshold row compile must keep today's decline")
				.isZero();
	}

	private List<String> generic(String query) {
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "false");
		try {
			return canonical(rows(query));
		} finally {
			System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		}
	}

	private List<String> nativeRows(String query) {
		return canonical(rows(query));
	}

	private List<BindingSet> rows(String query) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		}
	}

	private static List<String> canonical(List<BindingSet> rows) {
		List<String> result = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			List<String> bindings = new ArrayList<>(row.size());
			for (Binding binding : row) {
				bindings.add(binding.getName() + "=" + binding.getValue());
			}
			bindings.sort(String::compareTo);
			result.add(String.join("|", bindings));
		}
		result.sort(String::compareTo);
		return result;
	}
}
